defmodule AshPhoenixStarter.Farms.FarmInputApplication do
  use Ash.Resource,
    domain: Elixir.AshPhoenixStarter.Farms,
    data_layer: AshPostgres.DataLayer

  postgres do
    table "farm_input_applications"
  end

  multitenancy do
    strategy :context
  end

  preparations do
    prepare AshPhoenixStarter.Preparations.SetTenant
  end

  changes do
    change AshPhoenixStarter.Changes.SetTenant
  end

  attributes do
    # Primary Key generated by Postgres via uuid_generate_v7()
    uuid_primary_key :id do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :name, :string do
      allow_nil? false
      public? true
    end

    attribute :role, :string do
      allow_nil? false
      public? true
    end

    attribute :hire_date, :date do
      allow_nil? false
      public? true
    end

    attribute :hourly_rate, :decimal do
      allow_nil? false
      public? true
    end

    attribute :application_date, :date do
      allow_nil? false
      public? true
    end

    attribute :quantity_used, :float do
      allow_nil? false
      public? true
    end

    attribute :cost, :decimal do
      allow_nil? true
      public? true
    end

    # Database-managed timestamps
    attribute :inserted_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :updated_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end
  end

  relationships do
    belongs_to :planting, AshPhoenixStarter.Farms.FarmPlanting do
      attribute_type :uuid
      allow_nil? true
      public? true
    end

    belongs_to :input_type, AshPhoenixStarter.Farms.FarmInputType do
      attribute_type :uuid
      allow_nil? true
      public? true
    end
  end

  actions do
    defaults [:read, :destroy]

    create :create do
      primary? true
      accept [
        :name,
        :role,
        :hire_date,
        :hourly_rate,
        :application_date,
        :quantity_used,
        :cost,
        :planting_id,
        :input_type_id
      ]
    end

    update :update do
      primary? true
      accept [
        :name,
        :role,
        :hire_date,
        :hourly_rate,
        :application_date,
        :quantity_used,
        :cost,
        :planting_id,
        :input_type_id
      ]
    end
  end
end
